class Solution {
public:
    int smallestCommonElement(vector<vector<int>>& mat) {
        unordered_map<int, int> count;
        for (const auto& row : mat) {
            for (int value : row) {
                ++count[value];
            }
        }
        for (int value : mat[0]) {
            if (count[value] == static_cast<int>(mat.size())) {
                return value;
            }
        }
        return -1;
    }
};
